// @ts-ignore Generated by the OpenNext build.
import handler from './.open-next/worker.js'
import { closeWorkerRequest, runInWorkerRequest, type WorkerRequestScope } from './src/lib/worker-request-scope'
import { getRateLimitConfig } from './src/lib/route-rate-limits'
import { rateLimitHeaders } from './src/lib/rate-limit-memory'
import { securityOperation, type SecurityEnv } from './src/lib/cloudflare-security'
export { SecurityRateLimiter } from './src/cloudflare/security-rate-limiter'
// @ts-ignore Generated by OpenNext; needed when enabling the production ISR queue.
export { DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js'

interface Env extends SecurityEnv {
  MIGRATION_TEST_MODE?: string
  MIGRATION_TEST_DATABASE?: string
  MONGODB_URI?: string
  STRIPE_SECRET_KEY?: string
  PAYPAL_MODE?: string
  CRON_ENABLED?: string
  CRON_SECRET?: string
  NEXTAUTH_URL?: string
}

async function fetchRequest(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  if (env.MIGRATION_TEST_MODE === 'true' && (
    (env.MONGODB_URI && env.MIGRATION_TEST_DATABASE !== 'true') ||
    /^(sk|rk)_live_/.test(env.STRIPE_SECRET_KEY || '') || env.PAYPAL_MODE === 'live'
  )) return new Response('Configure an isolated test database and sandbox payments before testing.', { status: 503 })

  const rule = getRateLimitConfig(new URL(request.url).pathname)
  let apiHeaders: Record<string, string> | undefined
  if (rule) {
    try {
      // Cloudflare supplies this header. Never use a caller-controlled forwarded
      // chain as the primary identity on Workers.
      const ip = request.headers.get('cf-connecting-ip') || 'unknown'
      const path = new URL(request.url).pathname
      const short = path === '/api/auth/callback/credentials' ? env.LOGIN_LIMITER : env.API_LIMITER
      if (short && !(await short.limit({ key: `${path}:${ip}` })).success) {
        return Response.json({ error: 'Too many requests. Please try again later.' }, { status: 429, headers: { 'Retry-After': '60' } })
      }
      const result = await securityOperation(env, `${path}:${ip}`, 'limit', rule.max, rule.windowMs)
      if (!result.success) return Response.json({ error: 'Too many requests. Please try again later.' }, { status: 429, headers: rateLimitHeaders(result) })
      apiHeaders = rateLimitHeaders(result)
    } catch {
      return Response.json({ error: 'Request protection temporarily unavailable' }, { status: 503 })
    }
  }

  const scope: WorkerRequestScope = { values: new Map(), cleanup: [] }
  const pending = new Set<Promise<unknown>>()
  const context = new Proxy(ctx, {
    get(target, property) {
      if (property === 'waitUntil') return (promise: Promise<unknown>) => {
        pending.add(promise)
        void promise.then(() => pending.delete(promise), () => pending.delete(promise))
        target.waitUntil(promise)
      }
      const value = Reflect.get(target, property, target)
      return typeof value === 'function' ? value.bind(target) : value
    },
  })
  let bodyFinished!: () => void
  const bodyDone = new Promise<void>(resolve => { bodyFinished = resolve })
  ctx.waitUntil((async () => {
    await bodyDone
    while (pending.size) await Promise.allSettled([...pending])
    await closeWorkerRequest(scope)
  })())
  try {
    return await runInWorkerRequest(scope, async () => {
      const runtimeEnv = { ...env, CLOUDFLARE_WORKER: 'true' }
      const legacy = /^\/products\/[^/]+\/?$/.test(new URL(request.url).pathname)
      let missingLegacy = false
      if (legacy) {
        const lookup = new URL('/api/legacy-product-resolution', request.url)
        try { lookup.searchParams.set('slug', decodeURIComponent(new URL(request.url).pathname.split('/')[2])) } catch {
          bodyFinished(); return new Response(null, { status: 400 })
        }
        const resolved: Response = await handler.fetch(new Request(lookup), runtimeEnv, context)
        if (resolved.status === 301 || resolved.status >= 500) {
          bodyFinished()
          return resolved
        }
        missingLegacy = resolved.status === 404
        await resolved.arrayBuffer()
      }
      const response: Response = await handler.fetch(request, runtimeEnv, context)
      const headers = new Headers(response.headers)
      for (const [name, value] of Object.entries(apiHeaders || {})) headers.set(name, value)
      const status = missingLegacy && response.status === 200 ? 404
        : legacy && response.status === 308 && response.headers.has('location') ? 301 : response.status
      if (!response.body) { bodyFinished(); return new Response(null, { status, headers }) }
      const reader = response.body.getReader()
      const body = new ReadableStream({
        async pull(controller) {
          try {
            const { done, value } = await reader.read()
            if (done) { controller.close(); bodyFinished() } else controller.enqueue(value)
          } catch (error) { controller.error(error); bodyFinished() }
        },
        async cancel(reason) { try { await reader.cancel(reason) } finally { bodyFinished() } },
      })
      return new Response(body, { status, statusText: response.statusText, headers })
    })
  } catch (error) { bodyFinished(); throw error }
}

export default {
  fetch: fetchRequest,
  async scheduled(event: ScheduledController, env: Env, ctx: ExecutionContext) {
    if (env.CRON_ENABLED !== 'true') return
    if (env.MIGRATION_TEST_MODE === 'true') throw new Error('Scheduled customer messages are disabled in migration test mode')
    if (!env.CRON_SECRET || !env.NEXTAUTH_URL) throw new Error('CRON_SECRET and NEXTAUTH_URL are required')
    const path = event.cron === '0 * * * *' ? '/api/cron/abandoned-cart'
      : event.cron === '15 3 * * *' ? '/api/cron/review-requests' : null
    if (!path) throw new Error('Unknown cron schedule')
    // Invoke OpenNext directly. No public self-fetch, hostname dependency or
    // outbound request carrying the cron secret.
    const response = await fetchRequest(new Request(new URL(path, env.NEXTAUTH_URL), {
      headers: { authorization: `Bearer ${env.CRON_SECRET}`, 'cf-connecting-ip': 'scheduled' },
    }), env, ctx)
    await response.arrayBuffer()
    if (!response.ok) throw new Error(`Scheduled job failed: ${path} (${response.status})`)
  },
}
